align 16
SR___GETDS:
        RET

align 16
SR_CheckTimer:
; [rsp] = return address, [rsp+8] = _stack * of the recompiled code
        pushf
        mov r8d, [Game_TimerRun]
        cmp r8d, [Game_TimerTick]
        jne short SR_CheckTimer_RunTimer
        popf
        ret
    SR_CheckTimer_RunTimer:
        PUSH32 eax, ecx, edx, esi, edi
        mov r10, [rsp+2*8]      ; _stack *
        mov [r10], r11d
        call Game_RunTimer
        mov r10, [rsp+2*8]
        mov r11d, [r10]
        POP32 eax, ecx, edx, esi, edi
        popf
        ret

